package com.yeyamo_mobile.api.feed_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.feed_service.application.port.FeedOutboxPort;
@Component public class JpaFeedOutboxAdapter implements FeedOutboxPort{private final FeedOutboxRepository repo;private final ObjectMapper mapper;public JpaFeedOutboxAdapter(FeedOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,String aggregate,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Map<String,Object>e=new LinkedHashMap<>();e.put("eventId",id);e.put("eventType",type);e.put("eventVersion",1);e.put("occurredAt",Instant.now());e.put("producer","feed-service");e.put("aggregateType","feed-projection");e.put("aggregateId",aggregate);e.put("correlationId",correlation==null?id.toString():correlation);e.put("actorId","feed-projector");e.put("payload",payload);var row=new FeedOutboxEvent();row.setId(id);row.setAggregateId(aggregate);row.setEventType(type);row.setOccurredAt(Instant.now());row.setPayload(mapper.writeValueAsString(e));repo.save(row);}catch(Exception e){throw new IllegalStateException("Cannot create feed outbox event",e);}}}
